    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return {
    session,
    newGame,
    restart,
    rename,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    activate,
    resume,
  };
}

